/** A single video surface is kept attached when entering/leaving immersive mode. */
public final class CameraActivity extends AppPage implements SurfaceHolder.Callback {
    private String id;
    private JSONObject device=new JSONObject();
    private LinearLayout layout,heading,information,toolbar;
    private FrameLayout video,root;
    private SurfaceView surface;
    private TextView status,qualityLabel,connection;
    private View playButton,fullButton,exitFull;
    private boolean foreground,paused,fullscreen;
    private volatile int generation;private int quality=1;
    private volatile int renderedFrames;
    private NativeCameraSession session;private CameraPool.Lease lease;private int recoveryAttempt;private volatile long stableSince;
    private CameraDecoder decoder;private ScrollView informationScroll;private LinearLayout directionPad;private TextView recordButton,talkButton,listenButton;private volatile CameraRecording recording;private CameraAudio audio;private boolean listening,talkWanted;private long playbackStart,playbackEnd,lastMove;private int talkTurn;private String lastPtzResult="",lastTalkResult="",lastTalkDetail="";
    private final Handler main=new Handler(Looper.getMainLooper());
 private final Runnable recover=()->{if(foreground&&!paused){CameraPool.closeAll();connect();}};
    private final Runnable hideControls=()->{if(fullscreen&&renderedFrames>0){toolbar.setVisibility(View.GONE);exitFull.setVisibility(View.GONE);}};

    @Override public void onCreate(Bundle saved){
        super.onCreate(saved);id=getIntent().getStringExtra("id");
        if(id==null||!id.startsWith("mijia:")){finish();return;}
        JSONObject cached=MijiaCloud.cached(this,id);if(cached!=null)device=cached;
        root=new FrameLayout(this);root.setBackgroundColor(ui.background);layout=ui.column();root.addView(layout,new FrameLayout.LayoutParams(-1,-1));
        root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets b=insets.getInsets(fullscreen?WindowInsets.Type.displayCutout():WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(b.left,b.top,b.right,b.bottom);return insets;});
        heading=ui.row();heading.setPadding(ui.dp(16),ui.dp(8),ui.dp(16),ui.dp(8));heading.addView(iconButton("返回",AppUi.BACK,this::back));
        LinearLayout labels=ui.column();TextView title=ui.text(device.optString("title","监控"),20,ui.text,true);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.addView(title);labels.addView(ui.text(DeviceLocation.meta(device),11,ui.muted,false));
        LinearLayout.LayoutParams labelParams=new LinearLayout.LayoutParams(0,-2,1);labelParams.leftMargin=ui.dp(12);heading.addView(labels,labelParams);layout.addView(heading);
        video=new FrameLayout(this);video.setBackgroundColor(Color.BLACK);surface=new SurfaceView(this);surface.getHolder().addCallback(this);video.addView(surface,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));
        status=ui.text("准备连接实时画面…",14,Color.WHITE,false);status.setGravity(Gravity.CENTER);status.setPadding(ui.dp(28),ui.dp(16),ui.dp(28),ui.dp(52));video.addView(status,new FrameLayout.LayoutParams(-1,-1));
        layout.addView(video,new LinearLayout.LayoutParams(-1,ui.dp(240)));toolbar=ui.row();toolbar.setBackgroundColor(0xb3101513);toolbar.setPadding(ui.dp(8),0,ui.dp(8),0);
        playButton=tool("暂停观看",AppUi.PAUSE,()->{paused=!paused;if(paused){stop();status.setText("已暂停观看");status.setVisibility(View.VISIBLE);}else connect();patchTools();showControls();});toolbar.addView(playButton,new LinearLayout.LayoutParams(0,ui.dp(54),1));
        toolbar.addView(tool("重新连接",AppUi.REFRESH,()->{paused=false;recoveryAttempt=0;CameraPool.closeAll();connect();patchTools();showControls();}),new LinearLayout.LayoutParams(0,ui.dp(54),1));
        qualityLabel=ui.text("流畅 ⌄",13,Color.WHITE,true);qualityLabel.setGravity(Gravity.CENTER);qualityLabel.setContentDescription("监控清晰度");qualityLabel.setBackground(ui.ripple(0x00101513,12));qualityLabel.setOnClickListener(v->qualityMenu());toolbar.addView(qualityLabel,new LinearLayout.LayoutParams(0,ui.dp(54),1));
        fullButton=tool("全屏观看",AppUi.FULLSCREEN,()->setFullscreen(!fullscreen));toolbar.addView(fullButton,new LinearLayout.LayoutParams(0,ui.dp(54),1));layout.addView(toolbar,new LinearLayout.LayoutParams(-1,ui.dp(54)));
        exitFull=tool("退出全屏",AppUi.BACK,()->setFullscreen(false));exitFull.setVisibility(View.GONE);FrameLayout.LayoutParams exitParams=new FrameLayout.LayoutParams(ui.dp(76),ui.dp(54),Gravity.TOP|Gravity.LEFT);video.addView(exitFull,exitParams);
        video.setOnClickListener(v->{if(fullscreen&&toolbar.getVisibility()==View.VISIBLE){main.removeCallbacks(hideControls);toolbar.setVisibility(View.GONE);exitFull.setVisibility(View.GONE);}else showControls();});
        information=ui.column();information.setPadding(ui.dp(20),ui.dp(18),ui.dp(20),ui.dp(16));connection=ui.text("正在连接…",12,ui.muted,false);information.addView(connection);buildActions();informationScroll=new ScrollView(this);informationScroll.addView(information);layout.addView(informationScroll,new LinearLayout.LayoutParams(-1,0,1));
        setContentView(root);root.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{if(r-l!=or-ol||b-t!=ob-ot)resize();});resize();
        if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);
    }
    private View tool(String title,int icon,Runnable action){LinearLayout box=ui.column();box.setGravity(Gravity.CENTER);box.setFocusable(true);box.setClickable(true);box.setContentDescription(title);box.setBackground(ui.ripple(0x00101513,10));box.addView(ui.icon(icon,Color.WHITE,19));TextView label=ui.text(title,10,Color.WHITE,false);label.setGravity(Gravity.CENTER);box.addView(label);box.setOnClickListener(v->action.run());return box;}
    private void replaceTool(View view,String label,int icon){LinearLayout box=(LinearLayout)view;box.removeViewAt(0);View glyph=ui.icon(icon,Color.WHITE,19);box.addView(glyph,0);((TextView)box.getChildAt(1)).setText(label);box.setContentDescription(label);}
    private void patchTools(){replaceTool(playButton,paused?"继续观看":"暂停观看",paused?AppUi.PLAY:AppUi.PAUSE);replaceTool(fullButton,fullscreen?"退出全屏":"全屏观看",fullscreen?AppUi.COLLAPSE_SCREEN:AppUi.FULLSCREEN);}
    private void qualityMenu(){
        main.removeCallbacks(hideControls);LinearLayout rows=ui.column();rows.setPadding(ui.dp(6),ui.dp(6),ui.dp(6),ui.dp(6));PopupWindow popup=new PopupWindow(rows,ui.dp(150),ui.dp(116),true);popup.setBackgroundDrawable(ui.shape(ui.surface,16));popup.setElevation(ui.dp(8));popup.setOutsideTouchable(true);
        for(int q:new int[]{1,2}){TextView option=ui.text(q==1?"流畅":"高清",14,ui.text,false);option.setGravity(Gravity.CENTER_VERTICAL);option.setPadding(ui.dp(18),0,ui.dp(12),0);option.setBackground(ui.ripple(q==quality?ui.pale:ui.surface,12));option.setOnClickListener(v->{popup.dismiss();if(q!=quality){quality=q;qualityLabel.setText((q==1?"流畅":"高清")+" ⌄");qualityLabel.setStateDescription(q==1?"流畅":"高清");if(!paused)connect();}showControls();});rows.addView(option,new LinearLayout.LayoutParams(-1,ui.dp(52)));}popup.setOnDismissListener(this::showControls);popup.showAsDropDown(qualityLabel,0,ui.dp(4),Gravity.END);
    }
    private void showControls(){if(toolbar==null)return;toolbar.setVisibility(View.VISIBLE);exitFull.setVisibility(fullscreen?View.VISIBLE:View.GONE);main.removeCallbacks(hideControls);if(fullscreen&&renderedFrames>0)main.postDelayed(hideControls,3500);}
    private void setFullscreen(boolean value){if(fullscreen==value)return;fullscreen=value;heading.setVisibility(value?View.GONE:View.VISIBLE);informationScroll.setVisibility(value?View.GONE:View.VISIBLE);((ViewGroup)toolbar.getParent()).removeView(toolbar);if(value)video.addView(toolbar,new FrameLayout.LayoutParams(-1,ui.dp(54),Gravity.BOTTOM));else layout.addView(toolbar,layout.indexOfChild(video)+1,new LinearLayout.LayoutParams(-1,ui.dp(54)));root.setBackgroundColor(value?Color.BLACK:ui.background);patchTools();WindowInsetsController bars=getWindow().getInsetsController();if(bars!=null){bars.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);if(value)bars.hide(WindowInsets.Type.systemBars());else bars.show(WindowInsets.Type.systemBars());}setRequestedOrientation(value?ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);root.requestApplyInsets();resize();showControls();}
    private void resize(){if(video==null)return;int width=root.getWidth();if(width<=0)return;LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)video.getLayoutParams();int desired=fullscreen?0:Math.min(Math.round(width*9/16f),Math.round(Math.max(1,root.getHeight())*.48f));if(p.height!=desired||p.weight!=(fullscreen?1:0)){p.height=desired;p.weight=fullscreen?1:0;video.setLayoutParams(p);}video.post(()->{int w=video.getWidth(),h=Math.max(1,video.getHeight());int sw=w,sh=Math.round(w*9/16f);if(sh>h){sh=h;sw=Math.round(h*16/9f);}FrameLayout.LayoutParams sp=(FrameLayout.LayoutParams)surface.getLayoutParams();int gravity=fullscreen?Gravity.CENTER:Gravity.TOP|Gravity.CENTER_HORIZONTAL;if(sp.width!=sw||sp.height!=sh||sp.gravity!=gravity){sp.width=sw;sp.height=sh;sp.gravity=gravity;surface.setLayoutParams(sp);}});}
    private void back(){if(fullscreen)setFullscreen(false);else finish();}
    @Override public void onBackPressed(){back();}
    @Override public void onConfigurationChanged(Configuration config){super.onConfigurationChanged(config);resize();}
    @Override protected void onResume(){super.onResume();foreground=true;getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(!paused)connect();}
    @Override protected void onPause(){foreground=false;main.removeCallbacks(recover);stop();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);super.onPause();}
    @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);super.onDestroy();}
    @Override public void surfaceCreated(SurfaceHolder holder){if(session==null&&!paused)connect();}
    @Override public void surfaceChanged(SurfaceHolder holder,int format,int width,int height){}
    @Override public void surfaceDestroyed(SurfaceHolder holder){stop();}
    private void connect(){if(!foreground||paused||surface==null||!surface.getHolder().getSurface().isValid())return;main.removeCallbacks(recover);stop();final int token=++generation;renderedFrames=0;status.setVisibility(View.VISIBLE);showControls();
        if(!CameraPolicy.supported(device.optString("model"))){status.setText("此摄像头型号的视频连接仍在适配");return;}status.setText("正在连接实时画面…");connection.setText("正在连接…");audio=new CameraAudio();decoder=new CameraDecoder(surface.getHolder().getSurface(),()->{if(token!=generation)return;int count=++renderedFrames;if(count==1){stableSince=SystemClock.elapsedRealtime();}if(count==1)main.post(()->{if(token==generation){status.setVisibility(View.GONE);connection.setText(playbackStart>0?"存储卡回看":"实时画面 · "+(quality==1?"流畅":"高清"));showControls();}});});final CameraDecoder sink=decoder;
        NativeCameraSession.Listener listener=new NativeCameraSession.Listener(){public void status(String text){main.post(()->{if(token==generation&&renderedFrames==0){status.setText(text);connection.setText(text);}});}public void frame(int codec,long timestamp,byte[] data)throws Exception{if(token==generation){sink.accept(codec,timestamp,data);CameraRecording active=recording;if(active!=null)try{active.accept(codec,timestamp,data);}catch(Exception e){active.abort();recording=null;main.post(()->{recordButton.setText("录屏");message("录像未能保存，已停止");});}}}public void audio(int codec,int rate,int channels,byte[] data){if(token==generation&&listening&&audio!=null)try{audio.accept(codec,rate,channels,data);}catch(Exception e){main.post(()->{listening=false;setListening();message("当前音频未能播放");});}}public void control(String name,String code){main.post(()->{if(token==generation)controlResult(name,code);});}public void error(String message){main.post(()->{if(token!=generation)return;endTalk();finishRecording();status.setText(message);status.setVisibility(View.VISIBLE);connection.setText(message);showControls();long now=SystemClock.elapsedRealtime();if(stableSince>0&&now-stableSince>=30000)recoveryAttempt=0;stableSince=0;long wait=CameraReusePolicy.AUTO_RECOVERY_ENABLED?CameraReusePolicy.recoveryDelay(recoveryAttempt,foreground,paused,message):-1;if(wait>=0){recoveryAttempt++;status.setText("连接中断，正在重连（"+recoveryAttempt+"/3）…");main.postDelayed(recover,wait);}});}};if(playbackStart>0){CameraPool.closeAll();session=new NativeCameraSession(this,id,quality,playbackStart,playbackEnd,listener);session.start();}else{lease=CameraPool.acquire(this,id,quality,listener);session=lease.session;}
    }
    private void stop(){generation++;endTalk();finishRecording();if(lease!=null){CameraPool.release(lease);lease=null;}else if(session!=null)session.close();session=null;if(decoder!=null){decoder.close();decoder=null;}if(audio!=null){audio.close();audio=null;}listening=false;if(listenButton!=null)listenButton.setText("声音 · 关闭");}
    private void settings(){showControls();LinearLayout body=ui.column();TextView camera=action("摄像机设置");camera.setOnClickListener(v->new CameraSettingsDialog(this,ui,id,device).show());body.addView(camera,new LinearLayout.LayoutParams(-1,ui.dp(54)));ui.space(body,8);TextView storage=action("存储设置");storage.setOnClickListener(v->new CameraStorageDialog(this,ui,id,device).show());body.addView(storage,new LinearLayout.LayoutParams(-1,ui.dp(54)));AppSheet.show(this,"更多设置",body,null,null);}
    int renderedFrameCount(){return renderedFrames;}

    private TextView action(String label){TextView button=ui.text(label,14,ui.text,true);button.setGravity(Gravity.CENTER);button.setBackground(ui.ripple(ui.surface,15));button.setContentDescription(label);button.setFocusable(true);button.setClickable(true);return button;}
    private void buildActions(){ui.space(information,10);for(String[] group:new String[][]{{"对话","截图","录屏"},{"视角移动","回看","存储管理"}}){LinearLayout row=ui.row();for(String label:group){TextView button=action(label);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,ui.dp(60),1);if(row.getChildCount()>0)params.leftMargin=ui.dp(8);row.addView(button,params);switch(label){case "对话":talkButton=button;button.setContentDescription("按住对话");button.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){beginTalk();return true;}if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL){endTalk();return true;}return true;});button.setOnClickListener(v->{if(talkWanted)endTalk();else{beginTalk();final int turn=talkTurn;main.postDelayed(()->{if(turn==talkTurn)endTalk();},30000);}});break;case "截图":button.setOnClickListener(v->snapshot());break;case "录屏":recordButton=button;button.setOnClickListener(v->toggleRecording());break;case "视角移动":button.setOnClickListener(v->directionPad.setVisibility(directionPad.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));break;case "回看":button.setOnClickListener(v->playbackOptions());break;case "存储管理":button.setOnClickListener(v->new CameraStorageDialog(this,ui,id,device).show());break;}}information.addView(row);ui.space(information,8);}
        directionPad=ui.column();directionPad.setVisibility(View.GONE);for(String[] group:new String[][]{{"","上",""},{"左","","右"},{"","下",""}}){LinearLayout row=ui.row();for(String direction:group){View child;if(direction.isEmpty())child=new View(this);else{TextView button=action(direction);button.setContentDescription("镜头向"+direction+"移动");button.setOnClickListener(v->move(direction));child=button;}row.addView(child,new LinearLayout.LayoutParams(0,ui.dp(46),1));}directionPad.addView(row);}information.addView(directionPad);
        listenButton=action("声音 · 关闭");listenButton.setContentDescription("监听摄像头声音");listenButton.setOnClickListener(v->{listening=!listening;setListening();});information.addView(listenButton,new LinearLayout.LayoutParams(-1,ui.dp(44)));ui.space(information,10);TextView more=action("更多设置  ›");more.setContentDescription("更多设置");more.setOnClickListener(v->settings());information.addView(more,new LinearLayout.LayoutParams(-1,ui.dp(48)));
    }
    private boolean ready(){if(session!=null&&session.isReady()&&foreground&&!getSystemService(KeyguardManager.class).isDeviceLocked())return true;message("请先连接摄像头并保持手机解锁");return false;}
    private void message(String text){if(!isFinishing())Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
    private void command(String op){try{if(ready())session.control(new JSONObject().put("op",op));}catch(Exception e){message("指令未发送");}}
    private void move(String direction){if(!ready())return;long now=SystemClock.elapsedRealtime();if(now-lastMove<350)return;lastMove=now;int operation="左".equals(direction)?1:"右".equals(direction)?2:"上".equals(direction)?3:4;try{session.control(new JSONObject().put("op","ptz").put("direction",operation));}catch(Exception e){message("移动指令未发送");}}
    private void setListening(){if(!ready())listening=false;else try{session.control(new JSONObject().put("op","listen").put("enabled",listening));}catch(Exception e){listening=false;}listenButton.setText(listening?"声音 · 开启":"声音 · 关闭");}
    private void beginTalk(){if(!ready())return;final int turn=++talkTurn;if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},301);return;}talkWanted=true;talkButton.setText("正在连接对讲…");command("talk_start");main.postDelayed(()->{if(turn==talkTurn&&talkWanted&&talkButton.getText().toString().contains("连接")){endTalk();message("对讲未就绪，请稍后重试");}},5500);}
    private void endTalk(){talkTurn++;boolean wasWanted=talkWanted;talkWanted=false;if(audio!=null)audio.stopTalk();if(wasWanted&&session!=null&&session.isReady())try{session.control(new JSONObject().put("op","talk_stop"));}catch(Exception ignored){}if(talkButton!=null)talkButton.setText("对话");}
    private void controlResult(String name,String code){if("ptz_result".equals(name))lastPtzResult=code;if("talk_ready".equals(name)||"talk_failed".equals(name)){lastTalkResult=name;lastTalkDetail=code;}if("talk_ready".equals(name)&&talkWanted&&audio!=null){startTalkWhenReady(0);}else if("talk_failed".equals(name)){endTalk();message("摄像机对讲未就绪");}else if("ptz_result".equals(name)&&!"accepted".equals(code))message("镜头移动回执未确认，不会自动重发");else if("playback_result".equals(name)&&!"accepted".equals(code))connection.setText("回看回执未确认，正在等待实际画面");}
    private void startTalkWhenReady(int attempt){if(!talkWanted||session==null||audio==null)return;int codec=session.audioCodec();if(codec==0){if(attempt<25)main.postDelayed(()->startTalkWhenReady(attempt+1),100);else{endTalk();message("尚未取得对讲音频格式");}return;}talkButton.setText("松开结束");audio.startTalk(new CameraAudio.Sender(){public boolean send(byte[] packet){return talkWanted&&session!=null&&session.talkAudio(packet);}public void failed(String text){main.post(()->{endTalk();message(text);});}},codec,session.audioRate());}
    @Override public void onRequestPermissionsResult(int request,String[] names,int[] granted){super.onRequestPermissionsResult(request,names,granted);if(request==301)message(granted.length>0&&granted[0]==PackageManager.PERMISSION_GRANTED?"已授权，请再次按住对话":"未开启麦克风权限");}
    private void snapshot(){if(renderedFrames<1||!surface.getHolder().getSurface().isValid()){message("画面就绪后可以截图");return;}Bitmap image=Bitmap.createBitmap(Math.max(1,surface.getWidth()),Math.max(1,surface.getHeight()),Bitmap.Config.ARGB_8888);PixelCopy.request(surface,image,result->{if(result!=PixelCopy.SUCCESS){image.recycle();message("截图未完成，请重试");return;}new Thread(()->{String resultText;try{CameraCaptures.picture(this,id,image);resultText="截图已保存至相册 / JiaJu";}catch(Exception e){resultText="截图保存失败";}finally{image.recycle();}String feedback=resultText;main.post(()->message(feedback));},"JiaJuSavePicture").start();},main);}
    private void toggleRecording(){if(recording!=null){finishRecording();return;}if(decoder==null||renderedFrames<1){message("画面就绪后可以录屏");return;}try{MediaFormat format=decoder.recordingFormat();if(format==null)throw new IllegalStateException();recording=new CameraRecording(this,id,format);recordButton.setText("停止录屏");message("开始保存视频，再次点击停止");CameraRecording active=recording;main.postDelayed(()->{if(recording==active)finishRecording();},10*60*1000);}catch(Exception e){message("当前画面暂时无法录制");}}
    private void finishRecording(){CameraRecording old=recording;recording=null;if(recordButton!=null)recordButton.setText("录屏");if(old!=null)new Thread(()->{String result;try{old.stop();result="录像已保存至相册 / JiaJu";}catch(Exception e){result=e.getMessage()==null?"录像保存失败":e.getMessage();}String feedback=result;main.post(()->message(feedback));},"JiaJuSaveVideo").start();}
    private void playbackOptions(){final Dialog[] sheet=new Dialog[1];LinearLayout body=ui.column();TextView sd=action("存储卡回看");sd.setOnClickListener(v->{sheet[0].dismiss();choosePlaybackTime();});body.addView(sd,new LinearLayout.LayoutParams(-1,ui.dp(48)));ui.space(body,8);TextView live=action("返回实时画面");live.setOnClickListener(v->{sheet[0].dismiss();playbackStart=playbackEnd=0;paused=false;connect();message("已切换实时画面");});body.addView(live,new LinearLayout.LayoutParams(-1,ui.dp(48)));ui.space(body,14);body.addView(ui.text("本机截图与录像",14,ui.muted,true));JSONArray saved=CameraCaptures.list(this,id);for(int i=0;i<saved.length();i++){JSONObject item=saved.optJSONObject(i);if(item==null)continue;TextView file=action(item.optString("name"));file.setTextSize(12);file.setOnClickListener(v->CameraCaptures.open(this,item));body.addView(file,new LinearLayout.LayoutParams(-1,ui.dp(48)));ui.space(body,6);}if(saved.length()==0)body.addView(ui.text("本机尚无保存的截图或录像",13,ui.muted,false));sheet[0]=AppSheet.show(this,"回看",body,null,null);}
    private void choosePlaybackTime(){LinearLayout body=ui.column();DatePicker date=new DatePicker(this);date.setMaxDate(System.currentTimeMillis());body.addView(date);TimePicker time=new TimePicker(this);time.setIs24HourView(true);body.addView(time);body.addView(ui.text("选择存储卡已有录像的时间，播放十分钟；不会下载或保存录像。",13,ui.muted,false));final Dialog[] dialog=new Dialog[1];dialog[0]=AppSheet.show(this,"存储卡回看",body,"播放",()->{Calendar value=Calendar.getInstance();value.set(date.getYear(),date.getMonth(),date.getDayOfMonth(),time.getHour(),time.getMinute(),0);long start=value.getTimeInMillis()/1000,now=System.currentTimeMillis()/1000;if(start>=now){message("请选择当前时间之前的录像");return;}playbackStart=start;playbackEnd=Math.min(now,start+600);paused=false;dialog[0].dismiss();connect();});}
}
